import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { MarcheService } from '../../services/marche.service';
import { Marche, FiltreRecherche } from '../../models/marche.model';

@Component({
  selector: 'app-marche-list',
  templateUrl: './marche-list.component.html',
  styleUrls: ['./marche-list.component.scss']
})
export class MarcheListComponent implements OnInit {
  marches: Marche[] = [];
  isLoading = false;

  // ===== MODALE FICHIERS =====
  showFilesModal = false;
  selectedMarcheId: number | null = null;
  selectedFiles: any[] = [];
  filesLoading = false;
  fileCounts: { [key: number]: number } = {};

  constructor(private marcheService: MarcheService, private router: Router) {}

  ngOnInit(): void {
    this.loadMarches();
  }

  loadMarches(): void {
    this.isLoading = true;
    this.marcheService.getAllMarches().subscribe({
      next: (data) => {
        this.marches = data;
        this.isLoading = false;
        this.loadAllFileCounts();
      },
      error: (error) => {
        this.isLoading = false;
        console.error('Error loading marches:', error);
      }
    });
  }

  loadAllFileCounts(): void {
    this.marches.forEach(marche => {
      if (marche.id) {
        this.marcheService.getFiles(marche.id).subscribe({
          next: (files) => {
            this.fileCounts[marche.id!] = files.length;
          },
          error: () => { this.fileCounts[marche.id!] = 0; }
        });
      }
    });
  }

  getFileCount(marcheId: number): number {
    return this.fileCounts[marcheId] || 0;
  }

  rechercher(filtres: FiltreRecherche): void {
    this.isLoading = true;
    this.marcheService.rechercherMarches(filtres).subscribe({
      next: (data) => {
        this.marches = data;
        this.isLoading = false;
        this.loadAllFileCounts();
      },
      error: (error) => {
        this.isLoading = false;
        console.error('Erreur de recherche:', error);
      }
    });
  }

  navigateToCreate(): void {
    this.router.navigate(['/marches/nouveau']);
  }

  editMarche(id: number): void {
    this.router.navigate([`/marches/editer/${id}`]);
  }

  deleteMarche(id: number): void {
    if (confirm('Êtes-vous sûr de vouloir supprimer ce marché ?')) {
      this.marcheService.deleteMarche(id).subscribe({
        next: () => this.loadMarches(),
        error: (error) => console.error('Error deleting marche:', error)
      });
    }
  }

  refresh(): void {
    this.loadMarches();
  }

  voirDetails(id: number): void {
    this.router.navigate(['/marches/details', id]);
  }

  // ===== GESTION DES FICHIERS =====

  openFilesModal(marcheId: number): void {
    this.selectedMarcheId = marcheId;
    this.showFilesModal = true;
    this.filesLoading = true;
    this.selectedFiles = [];

    this.marcheService.getFiles(marcheId).subscribe({
      next: (files) => {
        this.selectedFiles = files;
        this.filesLoading = false;
      },
      error: (error) => {
        console.error('Erreur chargement fichiers:', error);
        this.filesLoading = false;
      }
    });
  }

  closeFilesModal(): void {
    this.showFilesModal = false;
    this.selectedMarcheId = null;
    this.selectedFiles = [];
    this.filesLoading = false;
  }

  downloadFile(marcheId: number, fileId: number, fileName: string): void {
    this.marcheService.downloadFile(marcheId, fileId).subscribe({
      next: (blob) => {
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = fileName;
        a.click();
        window.URL.revokeObjectURL(url);
      },
      error: (error) => console.error('Erreur téléchargement:', error)
    });
  }

  deleteFile(marcheId: number, fileId: number, index: number): void {
    if (confirm('Supprimer ce fichier ?')) {
      this.marcheService.deleteFile(marcheId, fileId).subscribe({
        next: () => {
          this.selectedFiles.splice(index, 1);
          this.fileCounts[marcheId] = (this.fileCounts[marcheId] || 1) - 1;
        },
        error: (error) => console.error('Erreur suppression:', error)
      });
    }
  }

  viewFile(url: string): void {
    window.open(url, '_blank');
  }

  getFileIcon(type: string): string {
    const icons: { [key: string]: string } = {
      'pdf': '📄', 'doc': '📝', 'docx': '📝',
      'xls': '📊', 'xlsx': '📊',
      'ppt': '📽️', 'pptx': '📽️',
      'jpg': '🖼️', 'jpeg': '🖼️', 'png': '🖼️',
      'mp4': '🎬', 'avi': '🎬',
      'mp3': '🎵',
      'zip': '📦', 'rar': '📦',
      'txt': '📃',
      'default': '📎'
    };
    return icons[type] || icons['default'];
  }
}
<div class="marche-list-container">
  <div class="header-actions">
    <h2>📋 Gestion des Marchés</h2>
    <div>
      <button class="btn btn-refresh" (click)="refresh()" title="Rafraîchir">🔄</button>
      <button class="btn btn-primary" (click)="navigateToCreate()">➕ Nouveau Marché</button>
    </div>
  </div>

  <app-recherche-marche (search)="rechercher($event)"></app-recherche-marche>

  <div class="table-container">
    <div *ngIf="isLoading" class="loading-spinner">⏳ Chargement...</div>

    <table class="table" *ngIf="!isLoading && marches.length > 0; else noData">
      <thead>
        <tr>
          <th>#</th>
          <th>Référence</th>
          <th>Objet</th>
          <th>Direction</th>
          <th>Statut</th>
          <th>Montant</th>
          <th>Région</th>
          <th>Date</th>
          <th>Fichiers</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr *ngFor="let marche of marches; let i = index">
          <td>{{ i + 1 }}</td>
          <td><strong>{{ marche.reference }}</strong></td>
          <td>{{ marche.objet }}</td>
          <td>{{ marche.direction }}</td>
          <td>
            <span class="badge" 
                  [class.badge-success]="marche.statut === 'ACTIF'"
                  [class.badge-warning]="marche.statut === 'EN_ATTENTE'"
                  [class.badge-secondary]="marche.statut === 'ARCHIVE'"
                  [class.badge-danger]="marche.statut === 'ANNULE'">
              {{ marche.statut }}
            </span>
          </td>
          <td>{{ marche.montant | number:'1.0-0' }} FCFA</td>
          <td>{{ marche.region || '-' }}</td>
          <td>{{ marche.dateCreation | date:'dd/MM/yyyy' }}</td>
          <td>
            <button class="btn btn-sm btn-secondary" (click)="openFilesModal(marche.id!)" title="Voir fichiers">
              📎 <span class="badge-file-count">{{ getFileCount(marche.id!) }}</span>
            </button>
          </td>
          <td>
            <button class="btn btn-sm btn-info" (click)="voirDetails(marche.id!)" title="Voir détails">👁️</button>
            <button class="btn btn-sm btn-warning" (click)="editMarche(marche.id!)" title="Modifier">✏️</button>
            <button class="btn btn-sm btn-danger" (click)="deleteMarche(marche.id!)" title="Supprimer">🗑️</button>
          </td>
        </tr>
      </tbody>
    </table>
    <ng-template #noData>
      <div class="empty-state">
        <p>📭 Aucun marché enregistré</p>
        <button class="btn btn-primary" (click)="navigateToCreate()">Créer votre premier marché</button>
      </div>
    </ng-template>
  </div>
</div>

<!-- ===== MODALE PIÈCES JOINTES ===== -->
<div class="modal-overlay" *ngIf="showFilesModal" (click.self)="closeFilesModal()">
  <div class="modal-content">
    <div class="modal-header">
      <h3>📎 Pièces jointes</h3>
      <button class="close-btn" (click)="closeFilesModal()">✕</button>
    </div>
    <div class="modal-body">
      <div *ngIf="filesLoading" class="loading-spinner">⏳ Chargement...</div>
      <div *ngIf="!filesLoading && selectedFiles.length === 0" class="empty-files">
        <p>📭 Aucun fichier joint</p>
      </div>
      <ul *ngIf="!filesLoading && selectedFiles.length > 0">
        <li *ngFor="let file of selectedFiles; let j = index">
          <span class="file-icon">{{ getFileIcon(file.type) }}</span>
          <span class="file-name">{{ file.nom }}</span>
          <span class="file-size">{{ file.taille | fileSize }}</span>
          <span class="file-date">{{ file.dateUpload | date:'dd/MM/yyyy HH:mm' }}</span>
          <div class="file-actions">
            <button class="btn-download" (click)="downloadFile(selectedMarcheId!, file.id!, file.nom)" title="Télécharger">⬇️</button>
            <button class="btn-view" (click)="viewFile(file.chemin)" title="Visualiser">👁️</button>
            <button class="btn-delete" (click)="deleteFile(selectedMarcheId!, file.id!, j)" title="Supprimer">🗑️</button>
          </div>
        </li>
      </ul>
    </div>
  </div>
</div>
